/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[FormDataSourceEventHandler(formDataSourceStr(SalesQuotationTable, SalesQuotationLine), FormDataSourceEventType::LeavingRecord)]
public void SalesQuotationLine_OnLeavingRecord(FormDataSource sender, FormDataSourceEventArgs e)
{
    SalesQuotationLine salesQuotationLine = sender.cursor() as SalesQuotationLine;
    if (salesQuotationLine.KCS_QLLVPosition)
    {
        this.parmPrevLVPos(salesQuotationLine.KCS_QLLVPosition);
        this.parmPrevInternalPos(salesQuotationLine.KCS_QLInternalPosition);
        this.parmPrevLineNum(salesQuotationLine.LineNum);
    }
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[FormDataSourceEventHandler(formDataSourceStr(SalesQuotationTable, SalesQuotationLine), FormDataSourceEventType::InitValue)]
public void SalesQuotationLine_OnInitValue(FormDataSource sender, FormDataSourceEventArgs e)
{
    SalesQuotationLine salesQuotationLine = sender.cursor() as SalesQuotationLine;
    if (!salesQuotationLine.salesquotationtable().AVAExistPositions())
    {
        salesQuotationLine.KCS_QLLVPosition = num2str(SalesQuotationline.salesQuotationTable().KCS_QLStdStepSize,0,0,-1,-1);
        if (this.parmAddGroup())
        {
            salesQuotationLine.KCS_QLInternalPosition = 1;
            this.parmAddGroup(false);
        }
        salesQuotationLine.LineNum = salesQuotationLine.buildLineNumFromLVPos();
    }
    else
    {
        salesQuotationLine.KCS_setNewLVInternalPos(this.parmPrevLVPos(), this.parmPrevInternalPos(), this.parmPrevLineNum(), this.parmAddGroup(),this.parmAddNewLVPos());
        this.parmAddGroup(false);
        this.parmAddNewLVPos(false);
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "mode">mode</param>
void updateDesign(InventDimFormDesignUpdate mode)
{
    InventMovement movement = InventMovement::construct(salesQuotationLine);
    InventDimControlIdCollection inventDimControlIdCollection;


    if (mode == InventDimFormDesignUpdate::Init)
    {
        if (!inventDimFormSetup)
        {
            inventDimControlIdCollection = InventDimControlIdCollection::construct();
            inventDimControlIdCollection.add(storageDimensions.id(), false);
            inventDimControlIdCollection.add(tracking.id(), false);
            inventDimControlIdCollection.add(productDimensions.id(), false);
            inventDimControlIdCollection.add(InventDimensionsGridAVA.id(), true);
            inventDimFormSetup = InventDimCtrl_Frm_Mov_OrderLine::newFromFormMovement(this, movement
                , null
                , inventDimControlIdCollection
                );
        }
    }

    next updateDesign(mode);

}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    next init();

    FormStringControl avaInventColorId_Grid = this.design().controlName(formControlStr(SalesQuotationTable, InventoryDimensionsGrid_InventColorId));
    avaInventColorId_Grid.registerOverrideMethod(methodStr(FormDataObject, lookup), methodStr(AVASalesTableFrm_Extension, avaColorLookup));
    FormStringControl avaInventColorId_GridAVA = this.design().controlName(formControlStr(SalesQuotationTable, InventDimensionsGridAVA_InventColorId));
    avaInventColorId_GridAVA.registerOverrideMethod(methodStr(FormDataObject, lookup), methodStr(AVASalesTableFrm_Extension, avaColorLookup));
    FormStringControl avaInventColorId_Details = this.design().controlName(formControlStr(SalesQuotationTable, InventoryDimensions_InventColorId));
    avaInventColorId_Details.registerOverrideMethod(methodStr(FormDataObject, lookup), methodStr(AVASalesTableFrm_Extension, avaColorLookup));

    this.design().controlName(FormControlStr(SalesQuotationTable, Manage)).visible(false);
    //LineStripQuotation
    this.design().controlName(FormControlStr(SalesQuotationTable, buttonDeliverySchedule)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, LineStripQuotationCalculateSeparator)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, SuppItemCalc_Quotation)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, LineStripQuotationSimulateSeparator)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, SalesQuotationPriceSim)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, MCRPriceHistory)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, KCS_BOSCommissSplitLine)).visible(false);
    //LineStripInventory
    this.design().controlName(FormControlStr(SalesQuotationTable, buttonLineInventLot)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, LineStripInventoryTraceSeparator)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, InventDimTracking)).visible(false);
    //LineOverviewActionButtonGroup
    this.design().controlName(FormControlStr(SalesQuotationTable, LineStripProduct)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, LineStripUpdate)).visible(false);

    //Sales
    this.design().controlName(FormControlStr(SalesQuotationTable, Sales_SalesCategory)).visible(false);
    this.design().controlName(FormControlStr(SalesQuotationTable, LinePosting)).visible(false);   

    SalesQuotationLine_ds.object(fieldNum(SalesQuotationLine, ItemId)).registerOverrideMethod(methodStr(FormDataObject, lookup), formMethodStr(SalesQuotationTable, avaOverrideItemIdLookup), this); 

    //this.design().controlName(FormControlStr(SalesQuotationTable, ITMments)).visible(false);
    this.design().controlName(formControlStr(SalesQuotationListPage, CreateActivity)).visible(false);
}

/// <summary>
///     method to override the lookup method of SalesQuotationLine dataSource field ItemId
/// </summary>
/// <param name = "_formControl">FormStringControl</param>
public void avaOverrideItemIdLookup(FormStringControl _formControl)
{
    FormDataObject avaSalesQuotationLine_ItemId = SalesQuotationLine_ds.object(fieldNum(SalesQuotationLine, ItemId));

    if (EcoResProductParameters::find().pcLookupMethod != PCLookupMethod::Configurable
        && isConfigurationkeyEnabled(configurationKeyNum(TradeItemSearch))
        && !EcoResProductSearchLookup::isProductSearchLookupEnabled())
    {
        this.avaItemIdLookup(_formControl, mcrSalesQuotationLine.SourceId);
    }
    else
    {
        avaSalesQuotationLine_ItemId.lookup(_formControl, _formControl.text());
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_formStringControl">_formStringControl</param>
public void avaColorLookup(FormStringControl _formStringControl)
{
    Args locArgs = new Args(identifierStr(AVAEcoResColorLookup));
    FormRun avaLookupFormRun;

    locArgs.record(SalesQuotationLine);
    locArgs.caller(this);

    avaLookupFormRun = classFactory::formRunClassOnClient(locArgs);
    avaLookupFormRun.init();

    _formStringControl.performFormLookup(avaLookupFormRun);
    avaLookupFormRun.wait();

}

/// <summary>
/// Creates lookup using the form InventItemIdLookupSimpleView
/// </summary>
/// <param name = "_formControl">FormStringControl</param>
/// <param name = "_sourceId">MCRSourceID</param>
public void avaItemIdLookup(FormStringControl _formControl, MCRSourceID _sourceId)
{
    Query                   avaQuery = new Query();
    InventLookupItemId      inventLookupItemId;

    QueryBuildDataSource    itemIdLookup_qbds   = avaQuery.addDataSource(tableNum(InventItemIdLookupSimpleView));
    Catalog                 catalog             = Catalog::find(MCRSourceCodeSetup::find(_sourceID).Catalog);

    itemIdLookup_qbds.addSortField(fieldNum(InventItemIdLookupSimpleView, ItemId));
    itemIdLookup_qbds.firstFast(true);

    if(MCRFullTextParameters::isProductSearchLookupSalesItemEnabled())
    {
        itemIdLookup_qbds.addRange(fieldNum(InventItemIdLookupSimpleView, KCS_IsSalesItem)).value(queryValue(NoYes::Yes));
    }

    if (catalog)
    {
        // Catalog exists, show items related to catalog
        QueryBuildDataSource queryBuildDataSourceCatalogProduct = itemIdLookup_qbds.addDataSource(tablenum(CatalogProduct));
        queryBuildDataSourceCatalogProduct.addLink(fieldNum(InventItemIdLookupSimpleView, Product), fieldNum(CatalogProduct, Product));
        queryBuildDataSourceCatalogProduct.joinMode(JoinMode::InnerJoin);

        queryBuildDataSourceCatalogProduct.addRange(fieldNum(CatalogProduct, Catalog)).value(queryValue(catalog.RecId));
    }
    else
    {
        // Catalog doesn't exist, show all items
        QueryBuildDataSource queryBuildDataSourceMCRInventTable = itemIdLookup_qbds.addDataSource(tableNum(MCRInventTable));
        queryBuildDataSourceMCRInventTable.relations(true);
        queryBuildDataSourceMCRInventTable.joinMode(JoinMode::NoExistsJoin);
        queryBuildDataSourceMCRInventTable.addRange(fieldnum(MCRInventTable, ContinuityScheduleId)).value(sysQuery::valueNotEmptyString());
    }

    inventLookupItemId = InventLookupItemId::newLookupCtrlQuery(_formControl, avaQuery);
    inventLookupItemId.run();
}

/// <summary>
/// contains all logic for dummy category items
/// </summary>
public void avaDummyCategoryLogic()
{
    boolean isDummy = InventTable::isDummy(salesQuotationLine.ItemId);

    enableDSField(salesQuotationLine_ds, fieldNum(SalesQuotationLine, Name), isDummy);
    enableDSField(salesQuotationLine_ds, fieldNum(SalesQuotationLine, NDXProductName1), isDummy);
    enableDSField(salesQuotationLine_ds, fieldNum(SalesQuotationLine, NDXProductName2), isDummy);
    enableDSField(salesQuotationLine_ds, fieldNum(SalesQuotationLine, KCS_ModelNumber), isDummy);

    if(isDummy)
    {
        salesQuotationLine.KCS_NotCalculated = isDummy;
    }

}

/// <summary>
///     AVA <c>showHeaderDocuments</c> method.
///     Displays the attchments for the given table buffer.
///     AVA - Schneider 18.04.2024
/// </summary>
/// <param name="_record">
///     <c>Common</c> as type
/// </param>
public void showHeaderDocuments()
{
    //Common          locCommon;
    FormDataSource  locFormDataSource;
    Args            locArgs;

    locFormDataSource = this.SalesQuotationTable_DS;
    this.design().controlName('HeaderView').setFocus();
    //locCommon = locFormDataSource.cursor();

    frmAlternativeDocCursor = locFormDataSource.cursor();

    if (frmAlternativeDocCursor)
    {
        locArgs = new Args(menuItemDisplayStr(DocuView));

        locArgs.caller(this);
        locArgs.record(frmAlternativeDocCursor);
        locArgs.menuItemName(menuitemDisplayStr(DocuView));
        locArgs.menuItemType(MenuItemType::Display);

        FormRun formRun = classfactory.formRunClass(locArgs);
        formRun.init();
        formRun.run();
        frmAlternativeDocCursor.clear();
        FormDataSource  salQuotDS = this.SalesQuotationLine_ds;
        frmAlternativeDocCursor = salQuotDS.cursor();
        formRun.wait();
        this.design().controlName('LineView').setFocus();
     //   frmAlternativeDocCursorOrg.clear();

    }
}

/// <summary>
///     AVA <c>docCursor</c> method.
///     AVA - Schneider 18.04.2024
/// </summary>
/// <param name="mode">
///     <c>SalesLine</c> as type
/// </param>
/// <returns>
///     <c>Common</c> as return value
/// </returns>
public Common docCursor()
{
    Common retVal;

    retVal = next docCursor();

    frmAlternativeDocCursorOrg = retVal;

    if(frmAlternativeDocCursor)
    {
        retVal = frmAlternativeDocCursor;
    }
    else if(frmAlternativeDocCursorOrg)
    {
        retVal = frmAlternativeDocCursorOrg;
    }

    return retVal;
}
